const generateAgents = (): Agent[] => {
    const agents: Agent[] = [];
    const strategyMap: { [key in StrategyType]: { count: number, symbols: string[] } } = {
        'Triangle Flag Breakout': { count: 8, symbols: ['EUR/USD', 'GBP/USD', 'SPY'] },
        'RR=3 Short': { count: 8, symbols: ['QQQ', 'TSLA', 'NVDA'] },
        'Market Making': { count: 6, symbols: ['SPXW', 'NDX'] },
        'Gamma Scalping': { count: 5, symbols: ['SPY', 'VIX'] },
        'Order Flow Imbalance': { count: 7, symbols: ['ES=F', 'NQ=F'] },
        'Macro Regime': { count: 4, symbols: ['^VIX', 'GLD', 'TLT'] },
        'Smart Money': { count: 6, symbols: ['BTC-USD', 'ETH-USD'] },
        'XAUUSD Hybrid EMA': { count: 5, symbols: ['XAUUSD'] },
        'AI Agent Trading Bot': { count: 5, symbols: ['BTC-USD', 'ETH-USD', 'SOL-USD'] },
        'XAUUSD Swing EMA-RSI': { count: 5, symbols: ['XAUUSD'] },
        'Polymarket Prediction Agent': { count: 5, symbols: ['Poly/Trump', 'Poly/FedRates', 'Poly/Bitcoin'] },
    };

    STRATEGIES.forEach(strategy => {
        const config = strategyMap[strategy.name];
        for (let i = 0; i < config.count; i++) {
            const id = `${strategy.name.split(' ').map(s => s[0]).join('')}_${i + 1}`;
            const status_rand = Math.random();
            let collaboration: string | undefined = undefined;
            COLLECTIVE_STATE.activeTaskForces.forEach(tf => {
                if (tf.members.includes(id)) {
                    collaboration = tf.name;
                }
            });
            
            // Assign lightweight tools based on strategy
            let tools: string[] = [];
            if (strategy.name === 'XAUUSD Hybrid EMA') {
                tools = ['hybrid_ema.py', 'volatility_guard.js', 'trend_scanner.sh', 'executor_mt5.py', 'hybrid_ema_system.mq5'];
            } else if (strategy.name === 'Triangle Flag Breakout') {
                 tools = ['pattern_recognition.cpp', 'market_depth.sh'];
            } else if (strategy.name === 'AI Agent Trading Bot') {
                 tools = ['autonomous_core.py', 'goal_seeker.js', 'memory_db.json'];
            } else if (strategy.name === 'XAUUSD Swing EMA-RSI') {
                 tools = ['swing_scanner.py', 'rsi_calc.js', 'xau_swing_ea.mq5'];
            } else if (strategy.name === 'Polymarket Prediction Agent') {
                 tools = ['polymarket_agent.py', 'consensus_engine.py', 'swarm_config.json'];
            } else {
                 tools = ['scraper_generic.js', 'sentiment_analyzer.py', 'execution_guard.sh'];
            }

            agents.push({
                id,
                type: agentTypeMap[strategy.name],
                strategy: strategy.name,
                status: status_rand < 0.8 ? 'active' : (status_rand < 0.9 ? 'monitoring' : (status_rand < 0.95 ? 'inactive' : 'error')),
                symbols: config.symbols,
                pnl: (Math.random() - 0.45) * 5000,
                trades: Math.floor(Math.random() * 20) + 5,
                collaboration,
                genomeVersion: `v1.${Math.floor(Math.random() * 5)}.${Math.floor(Math.random() * 10)}`,
                fitnessScore: 0.95 + (Math.random() * 0.1),
                genes: {
                    risk_tolerance: Math.random() * 0.5 + 0.5, // 0.5 - 1.0
                    adaptation_speed: Math.random() * 0.5 + 0.5, // 0.5 - 1.0
                    data_source_preference: Math.random() // 0.0 - 1.0
                },
                tools: tools
            });
        }
    });
    return agents.slice(0, 65); // Increased limit to accommodate new agents
};

const generatePnlHistory = (initialPnl: number): { time: string; pnl: number }[] => {
    const data = [];
    let currentPnl = initialPnl;
    const now = new Date();
    for (let i = 180; i >= 0; i--) {
        const time = new Date(now.getTime() - i * 60000);
        currentPnl += (Math.random() - 0.5) * 2000;
        data.push({
            time: time.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false }),
            pnl: Math.round(currentPnl)
        });
    }
    return data;
};

const LOG_MESSAGES: { level: LogLevel; message: string; agent?: boolean }[] = [
    { level: 'INFO', message: 'Executing trade on {symbol}. Size: {size} units.', agent: true },
    { level: 'INFO', message: 'Monitoring price action near key level for {strategy} setup.', agent: true },
    { level: 'WARN', message: 'Slippage detected on order execution for agent {agentId}.', agent: true },
    { level: 'CRITICAL', message: 'Risk parameter breached for agent {agentId}. Reducing exposure.', agent: true },
];

export const generateLogEntry = (agents: Agent[]): AuditLog => {
    const template = LOG_MESSAGES[Math.floor(Math.random() * LOG_MESSAGES.length)];
    const randomAgent = agents[Math.floor(Math.random() * agents.length)];
    
    let message = template.message;
    if (template.agent) {
        message = message.replace('{agentId}', randomAgent.id)
                         .replace('{symbol}', randomAgent.symbols[0])
                         .replace('{size}', (Math.random() * 100).toFixed(2))
                         .replace('{strategy}', randomAgent.strategy);
    }

    return {
        id: new Date().toISOString() + Math.random(),
        timestamp: new Date().toISOString(),
        level: template.level,
        message: message,
        agentId: template.agent ? randomAgent.id : undefined
    };
};

const generateInitialAuditLogs = (agents: Agent[], count: number): AuditLog[] => {
    return Array.from({ length: count }, () => generateLogEntry(agents));
};

const generateEvolutionHistory = (): EvolutionHistoryPoint[] => {
    const history: EvolutionHistoryPoint[] = [];
    let currentFitness = 1.05;
    const now = Date.now();
    for (let i = 60; i >= 0; i--) {
        history.push({
            timestamp: now - i * 60000 * 5, // 5 minutes per point
            fitness: currentFitness
        });
        currentFitness += (Math.random() - 0.4) * 0.01;
    }
    return history;
};

