const generatePredictions = (): Prediction[] => {
    const symbols = ['BTC-USD', 'SPY', 'NVDA', 'EUR/USD', 'TSLA', 'GLD', 'XAUUSD'];
    const horizons: Array<'1d' | '7d' | '30d'> = ['1d', '7d', '30d'];
    const r_tokens_pool = ["trend_down", "liquidity_thin", "entry_unconfirmed", "volume_spike", "macro_catalyst", "positive_sentiment", "insider_activity", "ema_cross"];
    const predictions: Prediction[] = [];

    symbols.forEach(symbol => {
        horizons.forEach(horizon => {
            const id = `${symbol}-${horizon}-${Date.now()}`;
            const predictedReturn = (Math.random() - 0.48) * 0.1;
            const uncertainty = Math.random() * 0.05;
            const confidence = Math.max(0.4, 1 - (uncertainty / (Math.abs(predictedReturn) + 1e-9)));
            const probabilityPositive = predictedReturn > 0 ? Math.min(0.95, confidence + 0.1) : Math.max(0.05, 1 - (confidence + 0.1));
            
            const daysMap = {"1d":1, "7d":7, "30d":30};
            const normalizedReturn = predictedReturn / daysMap[horizon];
            const edgeScore = normalizedReturn * probabilityPositive * confidence;

            const passesFilters = probabilityPositive > 0.7 && confidence > 0.6;
            
            let decision: 'Buy' | 'Sell' | 'Hold' = 'Hold';
            if (passesFilters) {
                if (predictedReturn > 0) decision = 'Buy';
                else decision = 'Sell';
            }

            predictions.push({
                id,
                symbol,
                horizon,
                predictedReturn,
                uncertainty,
                confidence,
                probabilityPositive,
                decision,
                reasoning: `Based on multi-factor analysis, the model predicts a ${predictedReturn > 0 ? 'positive' : 'negative'} drift over the ${horizon} horizon, driven by key reasoning tokens.`,
                risks: ["Market volatility", "Geopolitical events"],
                r_tokens: r_tokens_pool.sort(() => 0.5 - Math.random()).slice(0, 3),
                edgeScore,
                passesFilters,
            });
        });
    });

    return predictions.sort((a,b) => b.edgeScore - a.edgeScore);
};

