export const triggerEvolutionEvent = (prevState: SystemState): SystemState => {
    // Performance Optimization: Avoid full array copy if only one agent changes.
    const agents = [...prevState.agents]; 
    
    // 1. Selection: Find a low-performing agent (Reference kept, index needed)
    let targetAgent = agents[0];
    let targetIndex = 0;
    
    for (let i = 1; i < agents.length; i++) {
        if (agents[i].fitnessScore < targetAgent.fitnessScore) {
            targetAgent = agents[i];
            targetIndex = i;
        }
    }

    // Clone only the target agent to mutate
    const mutatedAgent = { ...targetAgent, genes: { ...targetAgent.genes } };

    // 2. Mutation: Pick a gene and mutate it
    const genes: (keyof Agent['genes'])[] = ['risk_tolerance', 'adaptation_speed', 'data_source_preference'];
    const geneToMutate = genes[Math.floor(Math.random() * genes.length)];
    
    const oldValue = mutatedAgent.genes[geneToMutate];
    const newValue = Math.max(0.1, Math.min(1.0, oldValue + (Math.random() - 0.5) * 0.2)); // Mutate by up to +/- 0.1
    mutatedAgent.genes[geneToMutate] = newValue;
    
    // 3. Evaluation: Update genome and fitness
    const oldVersionParts = mutatedAgent.genomeVersion.split('.').map(Number);
    mutatedAgent.genomeVersion = `v${oldVersionParts[0]}.${oldVersionParts[1] + 1}.${Math.floor(Math.random()*10)}`;
    const oldFitness = mutatedAgent.fitnessScore;
    mutatedAgent.fitnessScore *= (1 + (Math.random() * 0.05)); // Increase fitness by up to 5%

    // Replace in array
    agents[targetIndex] = mutatedAgent;

    // 4. Logging: Create a detailed audit log
    const reason = oldFitness < 0.9 ? 'performance decay' : 'environmental drift';
    const evolutionLog: AuditLog = {
        id: new Date().toISOString() + Math.random(),
        timestamp: new Date().toISOString(),
        level: 'EVOLUTION',
        agentId: mutatedAgent.id,
        message: `Genome mutated due to ${reason}. Gene '${geneToMutate}' changed from ${oldValue.toFixed(2)} to ${newValue.toFixed(2)}. Fitness increased to ${mutatedAgent.fitnessScore.toFixed(4)}.`
    };
    
    // 5. Update State
    const newFitness = agents.reduce((acc, agent) => acc + agent.fitnessScore, 0) / agents.length;
    const newHistory = [...prevState.evolutionaryState.history.slice(1), { timestamp: Date.now(), fitness: newFitness }];

    return {
        ...prevState,
        agents: agents, // New array, but mostly same object references.
        auditLogs: [evolutionLog, ...prevState.auditLogs].slice(0, 100),
        evolutionaryState: {
            currentFitness: newFitness,
            mutations: prevState.evolutionaryState.mutations + 1,
            history: newHistory,
            lastMutation: {
                agentId: mutatedAgent.id,
                gene: geneToMutate,
                oldValue,
                newValue,
                reason,
            }
        }
    };
};

export const processConsensusEvents = (prevState: SystemState): SystemState => {
    const newState = { 
        ...prevState, 
        consensusSignals: [...prevState.consensusSignals.map(s => ({...s, votes: [...s.votes]}))],
        auditLogs: [...prevState.auditLogs],
    };

    // 1. Chance to create a new signal if there are no pending ones
    const hasPendingSignals = newState.consensusSignals.some(s => s.status === 'pending');
    if (!hasPendingSignals && Math.random() < 0.2) { // 20% chance every cycle to create a new one
        const proposingAgent = newState.agents[Math.floor(Math.random() * newState.agents.length)];
        const eligibleVoters = newState.agents
            .filter(a => a.strategy === proposingAgent.strategy && a.id !== proposingAgent.id)
            .map(a => a.id);
        
        if (eligibleVoters.length > 2) {
            const newSignal: ConsensusSignal = {
                id: `CS-${Date.now()}`,
                proposingAgentId: proposingAgent.id,
                symbol: proposingAgent.symbols[Math.floor(Math.random() * proposingAgent.symbols.length)],
                side: Math.random() > 0.5 ? 'Buy' : 'Sell',
                strategy: proposingAgent.strategy,
                status: 'pending',
                votes: [],
                eligibleVoters,
                timestamp: new Date().toISOString(),
            };
            newState.consensusSignals.unshift(newSignal);

            const newLog: AuditLog = {
                id: `log-${Date.now()}`,
                timestamp: new Date().toISOString(),
                level: 'CONSENSUS',
                message: `New trade signal proposed by ${newSignal.proposingAgentId} for ${newSignal.side} ${newSignal.symbol}. Awaiting consensus from ${newSignal.eligibleVoters.length} agents.`
            };
            newState.auditLogs.unshift(newLog);
        }
    }

    // 2. Process votes for pending signals
    const pendingSignal = newState.consensusSignals.find(s => s.status === 'pending');
    if (pendingSignal) {
        // Find an agent who hasn't voted yet
        const voterId = pendingSignal.eligibleVoters.find(vId => !pendingSignal.votes.some(vote => vote.agentId === vId));

        if (voterId) {
            // Simulate a vote
            const rand = Math.random();
            const decision: VoteDecision = rand < 0.65 ? 'yes' : (rand < 0.9 ? 'no' : 'abstain');
            pendingSignal.votes.push({ agentId: voterId, decision });

            // 3. Check for resolution
            const yesVotes = pendingSignal.votes.filter(v => v.decision === 'yes').length;
            const noVotes = pendingSignal.votes.filter(v => v.decision === 'no').length;
            const totalVotes = pendingSignal.votes.length;
            const majorityThreshold = Math.ceil(pendingSignal.eligibleVoters.length / 2);

            let resolved = false;
            let newLog: AuditLog | null = null;

            // Resolve if one side gets a majority of ALL eligible voters
            if (yesVotes >= majorityThreshold) {
                pendingSignal.status = 'approved';
                resolved = true;
            } else if (noVotes >= majorityThreshold) {
                pendingSignal.status = 'rejected';
                resolved = true;
            } 
            // Or if all have voted
            else if (totalVotes === pendingSignal.eligibleVoters.length) {
                pendingSignal.status = yesVotes > noVotes ? 'approved' : 'rejected';
                resolved = true;
            }

            if (resolved) {
                pendingSignal.resolvedTimestamp = new Date().toISOString();
                newLog = {
                    id: `log-${Date.now()}`,
                    timestamp: new Date().toISOString(),
                    level: 'CONSENSUS',
                    message: `Consensus Reached for ${pendingSignal.side} ${pendingSignal.symbol}: ${pendingSignal.status.toUpperCase()} (${yesVotes} Yes / ${noVotes} No).`
                };
                newState.auditLogs.unshift(newLog);
            }
        }
    }

    // Cap consensus signals history
    newState.consensusSignals = newState.consensusSignals.slice(0, 20);

    return newState;
};

export const processAIBoardEvents = (prevState: SystemState): SystemState => {
    const newState = { 
        ...prevState, 
        aiBoardState: {
            ...prevState.aiBoardState,
            members: [...prevState.aiBoardState.members.map(m => ({...m}))],
            directives: [...prevState.aiBoardState.directives],
        },
        auditLogs: [...prevState.auditLogs],
    };

    // Chance for a member to change status
    if (Math.random() < 0.1) {
        const member = newState.aiBoardState.members.find(m => m.status === 'Recalibrating');
        if (member) {
            member.status = 'Online';
        } else {
            const onlineMember = newState.aiBoardState.members.find(m => m.status === 'Online');
            if (onlineMember) onlineMember.status = 'Recalibrating';
        }
    }
    
    // Chance for a new directive
    if (Math.random() < 0.15) {
        const onlineMembers = newState.aiBoardState.members.filter(m => m.status === 'Online');
        if (onlineMembers.length > 0) {
            const author = onlineMembers[Math.floor(Math.random() * onlineMembers.length)];
            const directives = [
                'Authorize Task Force Omega to explore quantum entanglement channels for data integrity verification.',
                'Mandate a system-wide recalibration of risk models based on emergent geopolitical narratives.',
                'Shift collective sentiment towards Defensive posture pending resolution of liquidity squeeze scenario.',
                'Prioritize evolution of agents demonstrating high fitness in volatile, low-liquidity environments.',
            ];
            const newDirective: AIBoardDirective = {
                id: `DIR-${Date.now()}`,
                timestamp: new Date().toISOString(),
                sourceModel: author.modelName,
                directive: directives[Math.floor(Math.random() * directives.length)],
            };
            newState.aiBoardState.directives.unshift(newDirective);
            newState.aiBoardState.directives = newState.aiBoardState.directives.slice(0, 10);

            const newLog: AuditLog = {
                 id: `log-${Date.now()}`,
                timestamp: new Date().toISOString(),
                level: 'BOARD',
                message: `New Board Directive from ${author.modelName}: "${newDirective.directive}"`
            };
             newState.auditLogs.unshift(newLog);
        }
    }

    return newState;
};

export const processBoardroomEvents = (prevState: SystemState): SystemState => {
    const newState = { ...prevState, boardEvents: [...prevState.boardEvents] };

    const r_tokens_pool = ["trend_down", "liquidity_thin", "entry_unconfirmed", "volume_spike", "macro_catalyst", "positive_sentiment", "insider_activity", "risk_aversion_high"];

    const generateVote = (modelName: AIBoardModel): ModelVote => {
        const confidence = Math.random() * 0.3 + 0.65; // 0.65 - 0.95
        const decision: 'approve' | 'reject' | 'hold' = Math.random() > 0.3 ? 'approve' : (Math.random() > 0.5 ? 'reject' : 'hold');
        return {
            modelName,
            decision,
            confidence,
            reasoning: `Analysis based on ${modelName}'s core competency. Confidence at ${(confidence * 100).toFixed(1)}%.`,
            r_tokens: r_tokens_pool.sort(() => 0.5 - Math.random()).slice(0, 2),
            risks: Math.random() > 0.7 ? ["elevated_volatility"] : [],
        };
    };

    const deepseekVote = generateVote('DeepSeek-V2');
    const qwenVote = generateVote('Qwen-Max');
    const gptVote = generateVote('GPT-4o');
    gptVote.decision = Math.random() > 0.1 ? 'approve' : 'reject'; // GPT is mostly a safety check

    const votes = [deepseekVote, qwenVote, gptVote];
    let finalDecision: ModelVote;
    let conflictDetected = false;

    // Consensus logic
    if (gptVote.decision === 'reject') {
        finalDecision = { ...gptVote, reasoning: `Compliance override: ${gptVote.reasoning}`};
    } else {
        const approveVotes = votes.filter(v => v.decision === 'approve').length;
        if (approveVotes >= 2) {
            finalDecision = deepseekVote.confidence > qwenVote.confidence ? deepseekVote : qwenVote;
            finalDecision.decision = 'approve';
        } else {
            finalDecision = deepseekVote.confidence > qwenVote.confidence ? deepseekVote : qwenVote;
            finalDecision.decision = 'hold';
        }
    }
    
    if (deepseekVote.decision !== qwenVote.decision) {
        conflictDetected = true;
    }

    const consensusScore = votes.reduce((acc, v) => acc + v.confidence, 0) / votes.length;
    
    const newEvent: BoardEvent = {
        id: `BE-${Date.now()}`,
        timestamp: new Date().toISOString(),
        agentRequest: {
            agentId: prevState.agents[Math.floor(Math.random() * prevState.agents.length)].id,
            task: `Evaluate trade signal on ${prevState.agents[0].symbols[0]}`
        },
        votes,
        finalDecision,
        consensusScore,
        conflictDetected
    };

    newState.boardEvents.unshift(newEvent);
    newState.boardEvents = newState.boardEvents.slice(0, 20);

    return newState;
};
